/*
 * src: /app/root/raf/static/quiz/Launcher.js
 */
Ext._define('raf.quiz.Launcher', {
    extend: 'toolkit.widget.TabPanel',

    getQuizGrid: function(cfg) {
        if (!this._quizGrid) {
            this._quizGrid = Ext._create('raf.quiz.Grid', {
                region: 'north',
                columnAction: false,
                gridAutoLoad: false,
                height: 300,
            });

            this._quizGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function(selm) {
                    if (selm.getSelections().length > 0)
                        this.quiz(selm.getSelections()[0].get('pk'));
                    else
                        this.quiz(null);
                }
            });

            this._quizGrid.setFilterProperty('activated', 'true', 100);
        }
        return this._quizGrid;
    },

    getItemGrid: function(cfg) {
        if (!this._itemGrid) {
            this._itemGrid = Ext._create('raf.item.Grid', {
                title: 'Assuntos',
                margins: '0 2 0 0',
                region: 'center',
                flex: 1,
                layout: 'fit',
                columnAction: false,
                gridAutoLoad: false,
                hideColumns: ['quiz_unicode'],
            });
        }

        return this._itemGrid;
    },

    getSubItemGrid: function(cfg) {
        if (!this._subitemGrid)
            this._subitemGrid = Ext._create('raf.subitem.Grid', {
                title: 'Movimentos',
                margins: '0 0 0 2',
                region: 'south',
                flex: 1,
                layout: 'fit',
                columnAction: false,
                gridAutoLoad: false,
                hideColumns: ['quiz_unicode'],
            });

        return this._subitemGrid;
    },

    quiz: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if (value !== undefined) {
            this._quiz = value;

            if (dispatch)
                this.observerQuiz();
        }

        return this._quiz;
    },

    observerQuiz: function() {
        var value = this.quiz();

        if (value) {
            this.getItemGrid().enable();
            this.getItemGrid().setParam('quiz', value);
            this.getItemGrid().setFilterProperty('quiz', value, 100);

            this.getSubItemGrid().enable();
            this.getSubItemGrid().setParam('quiz', value);
            this.getSubItemGrid().setFilterProperty('quiz', value, 100);
        } else {
            this.getItemGrid().disable();
            this.getItemGrid().setParam('quiz', 0);
            this.getItemGrid().setFilterProperty('quiz', 0, 100, false);
            this.getItemGrid().getStore().removeAll();

            this.getSubItemGrid().disable();
            this.getSubItemGrid().setParam('quiz', 0);
            this.getSubItemGrid().setFilterProperty('quiz', 0, 100, false);
            this.getSubItemGrid().getStore().removeAll();
        }
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Questionários'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getQuizGrid(cfg),
                    {

                        layout: {
                            type: 'hbox',
                            align: 'stretch'
                        },
                        region: 'center',
                        border: false,
                        items: [
                            this.getItemGrid(cfg),
                            this.getSubItemGrid(cfg)
                        ]
                    }
                ]
            }
        );

        raf.quiz.Launcher.superclass.constructor.call(this, cfg);

        this.quiz(cfg.oId === undefined ? null : cfg.oId);
    }
});

/*
 * src: /app/root/raf/static/quiz/FilterBaseWindow.js
 */

Ext._define('raf.quiz.FilterBaseWindow', {
    extend: 'Ext.Window',

    width: 450,

    properties: [],

    clearFilter: function() {
        var grid = this.grid;

        this.properties.forEach(
            function(directive) {
                if(directive.propertyAliases)
                    directive.propertyAliases.forEach(
                        function(alias) {
                            grid.removeFilterProperty(alias, directive.stage, false);
                        }
                    );
                else
                    grid.removeFilterProperty(directive.property, directive.stage, false);
            }
        );

        grid.getStore().load();
        this.close();
    },

    readFilters: function() {
        var filters = this.grid.getFilter();
        var properties = this.properties.map(
            function(directive) {
                return [directive.property, directive.propertyAliases];
            }
        );
        var values = {};

        properties.forEach(
            function(item) {
                var property, propertyAliases;

                property = item[0];
                propertyAliases = item[1] || [];

                if(Object.keys(values).indexOf(property) < 0)
                    filters.forEach(
                        function(directive) {
                            if(propertyAliases.indexOf(directive.property) >= 0 || property === directive.property)
                                values[property] = directive.value;
                        }
                    );
            }
        );

        this.getFormPanel().getForm().setValues(values);
    },

    applyFilter: function() {
        var values = this.getFormPanel().getForm().getValues();
        var me = this;

        this.properties.forEach(
            function(p) {
                if(p.propertyAliases)
                    p.propertyAliases.forEach(
                        function(alias) {
                            me.grid.setFilterProperty(
                                alias,
                                values[p.property],
                                p.stage,
                                false
                            );
                        }
                    );
                else
                    me.grid.setFilterProperty(
                        p.property,
                        values[p.property],
                        p.stage,
                        false
                    );
            }
        );

        this.grid.getStore().load();
        this.close();
    },

    getFormPanel: function(cfg) {
        throw 'O metodo getFormPanel deve ser implementado, este é abstrato';
    },

    getButtons: function(cfg) {
        if(!this._buttons)
            this._buttons = [
                {
                    text: 'Limpar',
                    scope: this,
                    handler: this.clearFilter
                },
                '->',
                {
                    text: 'Aplicar',
                    scope: this,
                    handler: this.applyFilter
                },
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function() {
                        this.close();
                    }
                }
            ];

        return this._buttons;
    },

    constructor: function(cfg) {
        cfg = (cfg || {});

        Ext.applyIf(
            cfg,
            {
                title: 'Filter Base Window',
                buttonAlign: 'left'
            }
        );

        Ext.apply(
            cfg,
            {
                buttons: this.getButtons(cfg),
                items: [
                    this.getFormPanel(cfg)
                ]
            }
        );

        raf.quiz.FilterBaseWindow.superclass.constructor.call(this, cfg);
    }
});

