Ext._define('raf.management.DefineDate', {
    extend: 'core.RestfulWindow',

    getValues: function(c) {
        var values = this.getFormPanel().getForm().getValues();
        values.validate = true;
        return values;
    },

    getEmployeeField: function() {
        if(!this._employeeField) {
            this._employeeField = Ext._create('core.fields.AutocompleteField', {
                xtype: "rest-autocompletefield",
                hideLabel: true,
                allowBlank: true,
                rest: "raf.EmployeeRestful",
                name: "employee",
                disabled: false,
                preFilter: [
                    {property: 'tipo', value: 'M', stage: 100},
                ],
                gridConfig: {
                    columnAction: false,
                    hideColumns: ['departure_unicode', 'effective_unicode', 'commission_unicode', 'elective_unicode', 'ativo'],
                    hideItemsToolbar: ['add', 'edit', 'remove', 'download', 'filter'],
                }
            });
        }
        return this._employeeField;
    },

    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                frame: true,
                labelWidth: 75,
                border: false,
                items: [
                    {
                        xtype:'fieldset',
                        title: 'Definções do agendamento',
                        collapsible: false,
                        autoHeight:true,
                        items: [
                            {
                                xtype:'panel',
                                autoHeight:true,
                                layout: 'column',
                                items: [
                                    {
                                        xtype:'panel',
                                        autoHeight:true,
                                        layout: 'form',
                                        labelWidth: 75,
                                        columnWidth: 0.63,
                                        items: [
                                            {
                                                fieldLabel: 'Tipo de ação',
                                                xtype: 'combo',
                                                hiddenName: 'action_type',
                                                width: 150,
                                                value: 1,
                                                store: [
                                                    [1, ''],
                                                    [2, 'ABERTURA'],
                                                    [3, 'FECHAMENTO'],
                                                ],
                                            }
                                        ]
                                    },
                                    {
                                        xtype:'panel',
                                        autoHeight:true,
                                        layout: 'form',
                                        labelWidth: 30,
                                        columnWidth: 0.37,
                                        items: [
                                            {
                                                xtype: 'datefield',
                                                fieldLabel: 'Data',
                                                name: 'generic_date',
                                            },
                                        ]
                                    },
                                ]
                            },
                        ]
                    },
                    {
                        xtype:'fieldset',
                        title: 'Membro',
                        collapsible: false,
                        autoHeight:true,
                        items: [
                            this.getEmployeeField(),
                        ]
                    },
                ]
        });
        return this._formPanel;
    },

    agendar: function(cfg) {
        var values = this.getValues(cfg);
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Agendamento ação no(s) RAF(s)...'});
        if (values.validate) {
            mask.show();
            Ext.Ajax.request({
                scope: this,
                url: core.callAction('RAFFunctionalActivityReport', 'defineDate'),
                callback: function() {
                    cfg.values.rafGrid.getStore().reload();
                    mask.hide();
                },
                success: function(request) {
                    var rst = Ext.decode(request.responseText);
                    Ext.Msg.show({
                        title: 'Agendamento de ações do RAF',
                        msg: rst.message,
                        icon: Ext.Msg.INFO,
                        buttons: Ext.Msg.OK
                    });
                    this.close();
                    core.invokeCallback((this.callback || {}).success);
                },
                failure: function(request) {
                    var rst = Ext.decode(request.responseText);
                    Ext.Msg.show({
                        title: 'Agendamento de ações do RAF',
                        msg: rst.message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                },
                params: {
                    action_type: values.action_type,
                    generic_date: values.generic_date,
                    month: cfg.values.month,
                    year: cfg.values.year,
                    employee: values.employee
                },
            });
        } else {
            Ext.Msg.show({
              title: 'Agendamento de ações do RAF',
              msg: values.message,
              icon: Ext.Msg.ERROR,
              buttons: Ext.Msg.OK
            });
        }
    },

    getButtons: function(cfg) {
        if(!this._buttons)
            this._buttons = [
                {
                    text: 'Agendar',
                    scope: this,
                    handler: function() { this.agendar(cfg); }
                },
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function() { this.close(); }
                }
            ];
        return this._buttons;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        Ext.applyIf(
            cfg,
            {
                title: 'Agendamento de ações do RAF',
                modal: true,
                resizable: false,
                border: false,
                width: 450,
            }
        );
        Ext.apply(
            cfg,
            {
                items: this.getFormPanel(),
                buttons: this.getButtons(cfg),
            }
        );
        raf.management.DefineDate.superclass.constructor.call(this, cfg);
    }
});

/*
 * src: /app/root/raf/static/management/SendEdocWindow.js
 */

Ext._define('raf.management.SendEdocWindow', {
    extend: 'Ext.Window',

    isEmpty: function(content) {
        let regex = /(<([^>]+)>)/ig;
        if(content.replace(regex, ""))
            return false
        return true
    },

    getEditor: function (cfg) {
        if (!this._ckeditoField) {
            cfg = core.nullValue(cfg, {});
            Ext.apply(cfg, {
                allowBlank: true,
                hideLabel: true,
                startupFocus: false,
                editorConfig: {
                    forcePasteAsPlainText: true
                },
            });
            this._ckeditoField = Ext._create('toolkit.fields.CKEditor', cfg);
        }
        return this._ckeditoField;
    },

    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                frame: true,
                border: false,
                hideLabel: true,
                items: [
                    this.getEditor({
                        name: 'content',
                        width: 900,
                        height: 385
                    })
                ]
        });
        return this._formPanel;
    },

    send: function() {

        var values = this.getFormPanel().getForm().getValues();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Enviando E-Doc...'});
        
        if (!this.isEmpty(values.content)) {
            
            mask.show();
            Ext.Ajax.request({
                scope: this,
                url: core.callAction('RAFFunctionalActivityReport', 'send_edoc'),
                callback: function() {
                    this.managementGroupGrid.getStore().reload();
                    mask.hide();
                },
                success: function(request) {
                    var rst = Ext.decode(request.responseText);
                    Ext.Msg.show({
                        title: 'Eviar E-Doc',
                        msg: rst.message,
                        icon: Ext.Msg.INFO,
                        buttons: Ext.Msg.OK
                    });
                    this.close();
                    core.invokeCallback((this.callback || {}).success);
                },
                failure: function(request) {
                    var rst = Ext.decode(request.responseText);
                    Ext.Msg.show({
                        title: 'Eviar E-Doc',
                        msg: 'Falha na solicitação',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                },
                params: {
                    month: this.params.month,
                    year: this.params.year,
                    content: values.content
                },
            });
        } else {
            Ext.Msg.show({
              title: 'Enviar E-Doc',
              msg: 'Conteúdo do documento encontra-se vazio. Digite o documento.',
              icon: Ext.Msg.ERROR,
              buttons: Ext.Msg.OK
            });
        }
    },

    getButtons: function(cfg) {
        if(!this._buttons)
            this._buttons = [
                {
                    text: 'Enviar',
                    scope: this,
                    handler: function() { this.send(); }
                },
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function() { this.close(); }
                }
            ];
        return this._buttons;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        Ext.applyIf(
            cfg,
            {
                title: 'Comunicar via E-doc',
                modal: true,
                resizable: false,
                border: false,
                width: 900,
            }
        );
        Ext.apply(
            cfg,
            {
                items: this.getFormPanel(),
                buttons: this.getButtons(cfg),
            }
        );
        raf.management.SendEdocWindow.superclass.constructor.call(this, cfg);
    }
});

/*
 * src: /app/root/raf/static/adjustment/BaseGrid.js
 */
Ext._define('raf.adjustment.BaseGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'raf.adjustment.BaseWindow',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'accept', 'requestInformation', 'answerInformation', 'cancelAdjustment', 'rejected', 'undoAction', 'searchprocessnumber', '->', '-'],

    openSearchProcessNumber: function() {
        Ext._create('raf.searchprocessnumber.SearchProcessNumberWindow', {
            modal: false,
            values: { }
        }).show();
    },

    getSearchProcessNumberAction: function() {
        if(!this._searchProcessNumberAction){
            this._searchProcessNumberAction = new Ext.Button({
                xtype: 'button',
                text: 'Pesquisar por número',
                iconCls: 'icon-core icon-core-select',
                scope: this,
                handler: function() { this.openSearchProcessNumber(); }
            });
        }
        return this._searchProcessNumberAction;
    },

    getCancelAdjustmentAction: function() {
        if(!this._cancelAdjustmentAction){
            this._cancelAdjustmentAction = new Ext.Button({
                xtype: 'button',
                text: 'Cancelar Solicitação',
                iconCls: 'icon-core icon-core-delete',
                scope: this,
                handler: function() {
                    var selected = this.getSelectionModel().getSelected();
                    if(selected) {
                        if ([1, 2, 3, 4, 6].indexOf(selected.data.situation) >= 0) {
                            Ext.Msg.show({
                                title: 'Cancelar solicitação',
                                msg: 'Cancelamento só possível para solicitações nos estados "NÃO ENVIADO" e "NÃO AVALIADO"',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK
                            });
                        } else {
                            Ext.Msg.show({
                                title: 'Cancelar solicitação',
                                icon: Ext.Msg.QUESTION,
                                buttons: Ext.Msg.YESNO,
                                msg: 'Tem certeza que deseja cancelar a solicitação selecionada?',
                                scope: this,
                                fn: function(btn) {
                                    if(btn == 'no') return;
                                    this.cancel(selected);
                                }
                            });
                        }
                    }
                    else
                        this.alertError({title: 'Cancelar', message: 'Selecione a solicitação que deseja cancelar.'});
                }
            });
        }
        return this._cancelAdjustmentAction;
    },

    cancel: function(value) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Cancelando solicitação...'});
        mask.show();
        rest.action(
            {
                adjustment_list: value.get('pk'),
                answer: 'Cancelado pelo usuário',
                situation: 4
            },
            {
                scope: this,
                fn: function(rst) {
                    if(rst.success) {
                        core.invokeCallback((this.callback || {}).success);
                        this.getStore().load({});
                        this.fireEvent('updatedItemGrid', value);
                        Ext.Msg.show({
                            title: 'Cancelar solicitação de ajuste',
                            msg: rst.message,
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK
                        });
                    }
                    else
                        Ext.Msg.show({
                            title: 'Cancelar solicitação de ajuste',
                            msg: rst.message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Cancelar solicitação de ajuste',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    alertError: function(wcfg) {
        Ext.Msg.show({
            title: wcfg.title,
            msg: wcfg.message,
            icon: Ext.Msg.ERROR,
            buttons: Ext.Msg.OK
        });
    },

    createItem: function(record) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Criando nova Solcitação de Ajustes...'});
        mask.show();
        rest.save(
            {
                activity: this.params.activity,
                workerlocation: this.params.workerlocation,
                // quiz: this.params.quiz,
                item: this.params.item,
                subitem: this.params.subitem,
            },
            {
                scope: this,
                fn: function(rst) {
                    if(rst.success) {
                        core.invokeCallback((this.callback || {}).success);
                        this.setFilterProperty('activity', rst.activity_id, 1000, true);
                        this.getStore().load({
                            'scope': this,
                            'callback': function() {
                                this.getSelectionModel().selectLastRow();
                                this.updateItem();
                                this.params.gridMain.getStore().reload();
                            }
                        });
                    }
                    else
                        Ext.Msg.show({
                            title: 'Criar Solicitação de Ajustes',
                            msg: rst.message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Criar Solicitação de Ajustes',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    updateItem: function(record) {
        var selected = this.getSelectionModel().getSelected();
        if(selected) {
            if (this.getSelectionModel().getSelections().length == 1){
                this.params.adjustment = selected.data.pk;
                this.params.activity = selected.data.activity;
                // this.params.quiz = this.selected.data.quiz;
                this.params.situation = selected.data.situation;
                raf.adjustment.BaseGrid.superclass.updateItem.call(this, record);
            }
            else {
                this.alertError({title: 'Solicitar mais informações', message: 'Selecione apenas um item para solicitar mais informações.'});
            }
        }
        else
            this.alertError({title: 'Solicitar mais informações', message: 'Selecione um item para solicitar mais informações.'});
    },

    getAcceptAction: function() {
        if(!this._acceptAction){
            this._acceptAction = new Ext.Button({
                xtype: 'button',
                text: 'Aceitar',
                iconCls: 'icon-core icon-core-success',
                scope: this,
                handler: function() {
                    var selection = this.getSelectionModel().getSelections();
                    if(selection) {
                        Ext.Msg.show({
                            title: 'Deferir solicitação',
                            icon: Ext.Msg.QUESTION,
                            buttons: Ext.Msg.YESNO,
                            msg: 'Tem certeza que deseja aceitar a solicitação selecionada?',
                            scope: this,
                            fn: function(btn) {
                                if(btn == 'no') return;
                                this.accept(selection.map(
                                        function(data) {
                                            return data.get('pk');
                                        }
                                    ).toString());
                            }
                        });
                    } else {
                        this.alertError({title: 'Aceitar', message: 'Selecione um item para aceitá-lo.'});
                    }
                }
            });
        }
        return this._acceptAction;
    },

    accept: function(value) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Realizando ajuste...'});
        mask.show();
        rest.action(
            {
                adjustment_list: value,
                answer: 'Deferido conforme a solicitação',
                situation: 2
            },
            {
                scope: this,
                fn: function(rst) {
                    if(rst.success) {
                        core.invokeCallback((this.callback || {}).success);
                        this.getStore().load({});
                        Ext.Msg.show({
                            title: 'Aceitar pedido de ajuste',
                            msg: rst.message,
                            icon: Ext.Msg.INFO,
                            buttons: Ext.Msg.OK
                        });
                    }
                    else
                        Ext.Msg.show({
                            title: 'Aceitar pedido de ajuste',
                            msg: rst.message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Aceitar pedido de ajuste',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    getRejectedAction: function() {
        if(!this._rejectedAction){
            this._rejectedAction = new Ext.Button({
                xtype: 'button',
                text: 'Rejeitar',
                iconCls: 'icon-core icon-core-error',
                scope: this,
                handler: function() {
                    var selection = this.getSelectionModel().getSelections();
                    if(selection) {
                        this.reject(selection.map(
                                function(data) {
                                    return data.get('pk');
                                }
                            ).toString());
                    }
                    else
                        this.alertError({title: 'Rejeitar', message: 'Selecione um item para rejeita-lo.'});
                }
            });
        }
        return this._rejectedAction;
    },

    reject: function(value) {
        Ext._create('raf.adjustment.RejectAdjustmentWindow', {
            modal: true,
            values: {
                adjustment_list: value,
                situation: 3,
            },
            callback: {
                success: {
                    scope: this,
                    fn: function(instance) {
                        core.invokeCallback((this.callback || {}).success);
                        this.getStore().load({});
                    }
                }
            }
        }).show();
    },

    getUndoAction: function() {
        if(!this._undoAction){
            this._undoAction = new Ext.Button({
                xtype: 'button',
                text: 'Desfazer decisão',
                iconCls: 'icon-core icon-core-remove-selected',
                scope: this,
                // disabled: true,
                handler: function() {
                    var selection = this.getSelectionModel().getSelections();
                    if(selection) {
                        // this.undoAction(selected);
                        this.undoAction(selection.map(
                                function(data) {
                                    return data.get('pk');
                                }
                            ).toString());
                    }
                    else
                        this.alertError({title: 'Desfazer', message: 'Selecione um item para desfazer decisão.'});
                }
            });
        }
        return this._undoAction;
    },

    undoAction: function(value) {
      Ext._create('raf.adjustment.UndoActionAdjustmentWindow', {
          modal: true,
          values: {
            //   adjustment: value.get('pk'),
              adjustment_list: value,
            //   activity_unicode : value.get('activity_unicode')
          },
          callback: {
              success: {
                  scope: this,
                  fn: function(instance) {
                      core.invokeCallback((this.callback || {}).success);
                      this.getStore().load({});
                  }
              }
          }
      }).show();
    },

    getRequestInformationAction: function() {
        if(!this._requestInformationAction){
            this._requestInformationAction = new Ext.Button({
                xtype: 'button',
                text: 'Solicitar mais informações',
                iconCls: 'icon-core icon-core-report-edit',
                scope: this,
                handler: function() {
                    var selected = this.getSelectionModel().getSelected();
                    if(selected) {
                        if (this.getSelectionModel().getSelections().length == 1){
                            this.openAdjustmentCommunicationWindow(selected);
                        }
                        else {
                            this.alertError({title: 'Solicitar mais informações', message: 'Selecione apenas um item para solicitar mais informações.'});
                        }
                    }
                    else
                        this.alertError({title: 'Solicitar mais informações', message: 'Selecione um item para solicitar mais informações.'});
                }
            });
        }
        return this._requestInformationAction;
    },

    openAdjustmentCommunicationForAdminWindow: function(value) {
        Ext._create('raf.conversation.AnswerWindow', {
            modal: true,
            values: {
                conversation: value.get('conversation'),
            },
            callback: {
                success: {
                    scope: this,
                    fn: function(instance) {
                        core.invokeCallback((this.callback || {}).success);
                        this.getStore().load({});
                    }
                }
            }
        }).show();
    },

    getAnswerInformationAction: function() {
        if(!this._answerInformationAction){
            this._answerInformationAction = new Ext.Button({
                xtype: 'button',
                text: 'Responder',
                iconCls: 'icon-core icon-core-report-edit',
                scope: this,
                handler: function() {
                    var selected = this.getSelectionModel().getSelected();
                    if(selected)
                        if ([2, 3, 4, 6].indexOf(selected.data.situation) >= 0) {
                            Ext.Msg.show({
                                title: 'Responder solicitação',
                                msg: 'Não é possível responder solicitações já encerradas',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK
                            });
                        } else {
                            this.openAdjustmentCommunicationWindow(selected);
                        }
                    else
                        this.alertError({title: 'Responder', message: 'Selecione o item que deseja responder.'});
                }
            });
        }
        return this._answerInformationAction;
    },

    openAdjustmentCommunicationWindow: function(value) {
        Ext._create('raf.conversation.AnswerWindow', {
            modal: true,
            values: {
                conversation: value.get('conversation'),
                origin: value.get('location'),
                situation: 0,
            },
            callback: {
                success: {
                    scope: this,
                    fn: function(instance) {
                        core.invokeCallback((this.callback || {}).success);
                        this.getStore().load({});
                    }
                }
            }
        }).show();
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 26, renderer: core.rendererIconGrid, menuDisabled: true},
                    {header: 'Atividade', dataIndex: 'unicode', id: 'autoExpandColumn', menuDisabled: true},
                    {header: 'Solicitação', dataIndex: 'activity_created_at', width: 120, menuDisabled: true,},
                    {header: 'status', dataIndex: 'status', width: 100, hidden: true, menuDisabled: true},
                    {header: 'Quantidade', dataIndex: 'amount', width: 60, hidden: true, menuDisabled: true},
                ]
            );

        return this._columnModel;
    },

    adjustment: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);
        if(value !== undefined) {
            this._adjustment = value;
            if(dispatch) this.observerAdjustment();
        }
        return this._adjustment;
    },

    observerAdjustment: function() {
        var value = this.adjustment();
        if(value) {
            this.readView(value);
        }
        else {
            this.detailView.disable();
            this.detailView.setPageContent('');
        }
    },

    readView: function(adjustment) {
        var mask = new Ext.LoadMask(this.detailView.getEl(), {msg: 'Carregado informações...'});
        var rest = this.factoryRestful();
        mask.show();
        this.detailView.enable();
        this.detailView.setPageContent('');
        Ext.Ajax.request({
            url: core.callAction(rest.resource, 'renderer_document'),
            scope: this,
            autoAbort: true,
            params: {
                adjustment: adjustment
            },
            callback: function() {
                mask.hide();
            },
            success: function(xhr) {
                var rst = Ext.decode(xhr.responseText);
                var me = this;
                if(rst.success) {
                    this.detailView.setPageContent(rst.content);
                }
                else
                    Ext.Msg.show({
                        title: 'Carregando informações',
                        msg: rst.message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
            },
            failure: function() {
                Ext.Msg.show({
                    title: 'Carregando informações',
                    msg: 'Recurso indisponivel no momento.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        });
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        Ext.applyIf(
            cfg,
            {
                colorized: false
            }
        );
        Ext.apply(
            cfg,
            {
                showFinished: true,
                viewConfig: {
                    getRowClass: function(record, rowIndex, rp, ds){
                        if(cfg.colorized && record.get('conversation_in_box'))
                            return 'x-grid3-green-simple';
                    }
                }
            }
        );
        raf.adjustment.BaseGrid.superclass.constructor.call(this, cfg);
        if((this.detailView)) {
            this.getSelectionModel().on({
                scope: this,
                selectionchange: function(sel) {
                    var selection = sel.getSelections();
                    if(selection.length > 0){
                        this.adjustment(selection[0].get('pk'));
                    } else {
                        this.adjustment(null);
                    }
                }
            });
            this.getStore().on({
                scope: this,
                load: function() {
                    this.observerAdjustment();
                },
            });
        }
    }
});

