/*
 * src: /app/root/raf/static/nonproceduralactivities/Manage.js
 */
Ext._define('raf.nonproceduralactivities.Manage', {
  extend: 'toolkit.widget.TabPanel',

  getGrid: function() {
    if(!this._grid)
      this._grid = Ext._create('raf.nonproceduralactivities.Grid', {
        region: 'center',
        gridAutoLoad: false,
        configOrderToolBar: ['add', 'edit', 'remove', '-', 'search'],
      });
    return this._grid;
  },

  getToolbar: function(cfg) {
      if(!this._toolbar) {
          this._toolbar = Ext._create('Ext.Toolbar', {
              buttonAlign:'center',
              items: [
                  this.getChangeEmployeeAction()
              ]
          });
      }
      return this._toolbar;
  },

  openChangeWindow: function() {
      Ext._create('raf.functionalactivityreport.ChangeEmployeeWindow', {
          modal: true,
          callback: {
              success: {
                  scope: this,
                  fn: function(instance) {
                      this.employeeSelected(instance);
                  }
              }
          }
      }).show();
  },

  getChangeEmployeeAction: function() {
      if(!this._changeEmployeeAction){
          this._changeEmployeeAction = new Ext.Button({
              xtype: 'button',
              text: this.defaultText(),
              iconCls: 'icon-core icon-core-set-employee',
              scope: this,
              handler: function() {
                  this.openChangeWindow();
              }
          });
      }
      return this._changeEmployeeAction;
  },

  employeeSelected: function(instance) {
      if(instance) {
          this.getChangeEmployeeAction().setText(instance.data.pessoa_fisica_unicode);
          this.employee(instance.data.pk);
      } else if(!this.employee()){
          this.getChangeEmployeeAction().setText(this.defaultText());
          this.employee(null);
      }
  },

  defaultText: function() {
      return "Clique aqui para selecionar um Membro"
  },

  getChangeEmployeeAction: function() {
      if(!this._changeEmployeeAction){
          this._changeEmployeeAction = new Ext.Button({
              xtype: 'button',
              text: this.defaultText(),
              iconCls: 'icon-core icon-core-set-employee',
              scope: this,
              handler: function() {
                  this.openChangeWindow()
              }
          });
      }
      return this._changeEmployeeAction;
  },

  autoSelectionEmployee: function() {
      if(this.employee() === undefined) {
          var rest = Ext._create('raf.EmployeeRestful');
          var mask = new Ext.LoadMask(this.getEl(), {msg: 'Selecionando usuário...'});
          mask.show();
          rest.doRequest(
              rest.getRoute('employee_initial', false, 'GET', {
                  scope: this,
                  callback: function() {
                      mask.hide();
                      mask = null;
                  },
                  success: function(xhr) {
                      var rst = Ext.decode(xhr.responseText);
                      if(rst.success) {
                          this.employeeSelected(rst);
                      }
                      else
                          Ext.Msg.show({
                              title: 'Selecionando usuário',
                              icon: Ext.Msg.ERROR,
                              buttons: Ext.Msg.OK,
                              msg: rst.message
                          });
                  },
                  failure: function(xhr) {
                      Ext.Msg.show({
                          title: 'Selecionando usuário',
                          icon: Ext.Msg.ERROR,
                          buttons: Ext.Msg.OK,
                          msg: 'Nao foi possível realizar essa operação.'
                      });
                  }
              })
          );
      }
  },

  employee: function(value, dispatch) {
      dispatch = (dispatch === undefined ? true : dispatch);
      if(value !== undefined) {
          this._employee = value;

          if(dispatch) this.observerEmployee();
      }
      return this._employee;
  },

  observerEmployee: function() {
      var value = this.employee();
      if(value) {
          this.getGrid().setParam('member', value);
          this.getGrid().setFilterProperty('member', value, 1000);
      } else {
          this.getGrid().setParam('member', 0);
          this.getGrid().setFilterProperty('member', 0, 1000, false);
          this.getGrid().getStore().removeAll();
      }
  },

  constructor: function(cfg) {
      cfg = cfg ? cfg : {};
      Ext.applyIf(
          cfg,
          {
              title: 'Gestor de Atividades Não Procedimentais'
          }
      );
      Ext.apply(
          cfg,
          {
              layout: 'border',
              items: this.getGrid(),
              tbar: this.getToolbar(),
          }
      );
      raf.nonproceduralactivities.Manage.superclass.constructor.call(this, cfg);
      this.autoSelectionEmployee();
    },
});

/*
 * src: /app/root/raf/static/searchprocessnumber/SearchProcessNumberWindow.js
 */
Ext._define('raf.searchprocessnumber.SearchProcessNumberWindow', {
    extend: 'core.RestfulWindow',

    clear_process_number: function(value) {
        proc = value.replace(/\./g,'').replace(/\-/g,'').replace(/\//g,'');
        while (proc[0] == '0') {
            proc = proc.replace('0', '');
        }
        return proc;
    },

    pesquisar: function(cfg) {
        if (this.getFormPanel(cfg).getForm().getValues().process_number) {
            if (this.getFormPanel(cfg).getForm().getValues().source) {
                source = this.getFormPanel(cfg).getForm().getValues().source;
                proc = this.clear_process_number(this.getFormPanel(cfg).getForm().getValues().process_number);

                this.getProcessGrid().setFilterProperty('source', source, 101, false);
                this.getProcessGrid().setFilterProperty('process_number', proc, 102, true);

            } else {
                Ext.Msg.show({
                    title: 'Pesquisar por número',
                    msg: 'Selecione uma <b>ORIGEM</b> para realização da pesquisa.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        } else {
            Ext.Msg.show({
                title: 'Pesquisar por número',
                msg: 'Informe um <b>NÚMERO DE PROCESSO</b> para realização da pesquisa.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
        }
    },

    getProcessGrid: function() {
        if(!this._processGrid) {
            this._processGrid = Ext._create('raf.searchprocessnumber.Grid', {
                 region: 'center',
                 layout: 'fit',
                 border: false,
                 height: 500,
                 gridAutoLoad: false,
                 columnAction: false,
                 hideItemsToolbar:['add', 'edit', 'remove', 'download', '-', 'search'],
                 hiddenFilter: true,
                 doubleClickHandler: function(){},
            });
            this._processGrid.setFilterProperty('source', 0, 101, false);
            this._processGrid.setFilterProperty('process_number', 0, 102, true);
        }
        this._processGrid.enable();
        return this._processGrid;
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                frame: true,
                border: false,
                items: [
                    {
                        xtype:'panel',
                        autoHeight: true,
                        layout: 'column',
                        items: [
                            {
                                xtype:'panel',
                                autoHeight:true,
                                layout: 'form',
                                labelWidth: 120,
                                columnWidth: 0.65,
                                items: [
                                    {
                                        xtype: 'textfield',
                                        fieldLabel: 'Número do Processo',
                                        name: 'process_number',
                                        hideLabel: false,
                                        width: 560,
                                    },
                                ]
                            },
                            {
                                xtype:'panel',
                                autoHeight:true,
                                layout: 'form',
                                labelWidth: 45,
                                columnWidth: 0.20,
                                items: [
                                    {
                                        xtype: 'choicefield',
                                        fieldLabel: 'Origem',
                                        hiddenName: 'source',
                                        width: 150,
                                        choiceId: 'raf.ACTIVITY_SOURCE',
                                    },
                                ]
                            },
                            {
                                xtype:'panel',
                                autoHeight:true,
                                layout: 'form',
                                labelWidth: 45,
                                columnWidth: 0.15,
                                items: [
                                    {
                                        xtype: 'button',
                                        text: 'Pesquisar',
                                        iconCls: 'icon-core icon-core-select',
                                        scope: this,
                                        width: 150,
                                        handler: function(cfg) { this.pesquisar(cfg); },
                                    }
                                ]
                            },
                        ]
                    },
                    this.getProcessGrid()
                ]
        });
        return this._formPanel;
    },

    getButtons: function() {
        if(!this._buttons)
            this._buttons = [
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function() { this.close(); }
                }
            ];
        return this._buttons;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        this.filtered = false;
        if (cfg.hasOwnProperty("params")) {
            if (cfg.params.hasOwnProperty("process_number")) {
                this.filtered = true;
            } else {
                cfg.params.process_number = 0;
            }
        }
        Ext.applyIf(
            cfg,
            {
                title: 'Pesquisar por Número',
                modal: true,
                resizable: false,
                border: false,
                width: 1100,
                height: 605,
            }
        );
        Ext.apply(
            cfg,
            {
                items: this.getFormPanel(cfg),
                buttons: this.getButtons(),
            }
        );
        raf.searchprocessnumber.SearchProcessNumberWindow.superclass.constructor.call(this, cfg);
        if (this.filtered) {
            this.getFormPanel(cfg).getForm().setValues({
                'process_number': cfg.params.process_number,
                'source': cfg.params.source,
            });
            // proc = this.clear_process_number(cfg.params.process_number);
            // this.getProcessGrid().setFilterProperty('source', cfg.params.source, 101, false);
            // this.getProcessGrid().setFilterProperty('process_number__icontains', proc, 102, true);
        }
    }
});

/*
 * src: /app/root/raf/static/searchprocessnumber/Grid.js
 */
Ext._define('raf.searchprocessnumber.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'raf.searchprocessnumber.Window',
    pageSize: 10,

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'unicode', id: 'autoExpandColumn', hidden: true},
                    {header: 'Processo', dataIndex: 'data_processo', width: 450},
                    {header: 'RAF', dataIndex: 'data_raf', width: 500},
                    {header: '', xtype: 'actioncolumn', width: 50, scope: this, menuDisabled: true,
                        items: [
                            {
                                tooltip: 'Mais informações...',
                                icon: '/'+ global.Context + '/static/images/icons/document-arrow.png',
                                scope:this,
                                handler: function(grid, row, col) {
                                    grid.getSelectionModel().selectRow(row);
                                    var record = grid.getStore().getAt(row);
                                    if (record.data.autoreference_source_add == 1)
                                        if (record.data.autoreference_is_adjustment == false)
                                            Ext._create('raf.autoreference.DataEprocWindow', {
                                                params: {
                                                    autoreference: record.data.autoreference_id,
                                                }
                                            }).show();
                                        else {
                                            Ext._create('raf.autoreference.DataAdjustmentWindow', {
                                                params: {
                                                    autoreference: record.data.autoreference_id,
                                                }
                                            }).show();
                                        }
                                    if (record.data.autoreference_source_add == 2)
                                        if (record.data.autoreference_is_adjustment == false)
                                            Ext._create('raf.autoreference.DataEExtWindow', {
                                                params: {
                                                    autoreference: record.data.autoreference_id,
                                                }
                                            }).show();
                                        else {
                                            Ext._create('raf.autoreference.DataAdjustmentWindow', {
                                                params: {
                                                    autoreference: record.data.autoreference_id,
                                                }
                                            }).show();
                                        }
                                    if (record.data.autoreference_source_add == 3)
                                        if (record.data.autoreference_is_adjustment == false)
                                            Ext._create('raf.autoreference.AttendanceWindow', {
                                                params: {
                                                    autoreference: record.data.autoreference_id,
                                                }
                                            }).show();
                                        else {
                                            Ext._create('raf.autoreference.DataAdjustmentWindow', {
                                                params: {
                                                    autoreference: record.data.autoreference_id,
                                                }
                                            }).show();
                                        }
                                    if (record.data.autoreference_source_add == 4)
                                        Ext._create('raf.autoreference.DataAdjustmentWindow', {
                                            params: {
                                                autoreference: record.data.autoreference_id,
                                            }
                                        }).show();
                                }
                            },
                        ]
                    },
                ]
            );
        return this._columnModel;
    }

});

